// VehicleLoop.cs is generated by Gemini

using UnityEngine;

public class VehicleLoop : MonoBehaviour
{
    [Tooltip("Speed and direction. Use a negative number to move the opposite way.")]
    public float speed = -10f; 
    
    [Tooltip("The Z coordinate where the vehicle disappears (e.g., far left)")]
    public float despawnZ = -30f;
    
    [Tooltip("The Z coordinate where the vehicle reappears (e.g., far right)")]
    public float respawnZ = 30f;

    void Update()
    {
        // Move the vehicle strictly along the global Z axis
        transform.position += new Vector3(0, 0, speed * Time.deltaTime);

        // Check if the vehicle has crossed the despawn threshold
        if (speed < 0 && transform.position.z <= despawnZ)
        {
            ResetPosition();
        }
        else if (speed > 0 && transform.position.z >= despawnZ)
        {
            ResetPosition();
        }
    }

    private void ResetPosition()
    {
        Vector3 newPos = transform.position;
        newPos.z = respawnZ;
        transform.position = newPos;
    }
}
